        FrameworkElement Parameter(string zh,string en,string enabled,string field,double min,double max,double tick){var grid=new Grid {Margin=new Thickness(0,0,0,12)};grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(130)});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(80)});var slider=new Slider {Minimum=min,Maximum=max,TickFrequency=tick,IsSnapToTickEnabled=true,Value=Math.Max(min,Math.Min(max,settings.Number(field,min))),IsEnabled=settings.Flag(enabled)};var number=Field(settings.Number(field,min).ToString(System.Globalization.CultureInfo.InvariantCulture),v=>{if(!syncingApi&&double.TryParse(v,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out double n)&&n>=min&&n<=max){settings.Values[field]=n;slider.Value=n;}});number.Margin=new Thickness(12,0,0,0);number.IsEnabled=slider.IsEnabled;var check=Check(zh,en,enabled,()=>{slider.IsEnabled=number.IsEnabled=settings.Flag(enabled);});check.VerticalAlignment=VerticalAlignment.Center;grid.Children.Add(check);Grid.SetColumn(slider,1);grid.Children.Add(slider);Grid.SetColumn(number,2);grid.Children.Add(number);apiSync.Add(()=>{slider.Value=settings.Number(field,min);number.Text=settings.Number(field,min).ToString(System.Globalization.CultureInfo.InvariantCulture);slider.IsEnabled=number.IsEnabled=settings.Flag(enabled);check.IsChecked=settings.Flag(enabled);});slider.ValueChanged+=(s,e)=>{if(syncingApi)return;settings.Values[field]=slider.Value;number.Text=slider.Value.ToString(field=="temperature"?"0.0":"0",System.Globalization.CultureInfo.InvariantCulture);};return grid;}
