        void UpdateProvider(){if(homeProvider!=null&&homeProvider.SelectedItem as string!=settings.Text("provider"))homeProvider.SelectedItem=settings.Text("provider");if(deepseekOptions!=null)deepseekOptions.Visibility=settings.Text("provider")=="Bing"?Visibility.Collapsed:Visibility.Visible;if(serviceLabel!=null)serviceLabel.Text=settings.Text("provider")=="Bing"?"Bing":settings.Text("provider")+(settings.Flag("reasoning_enabled")&&!settings.Flag("economy_mode")?L(" · 思考模式"," · Thinking"):"");}
        bool LooksSensitive(string text){return TextTools.LooksSensitive(text,settings.Key)||apiStates.Values.Any(x=>TextTools.LooksSensitive(text,x.Key));}
        void SelectApiService(string name){
            if(syncingApi||!ApiServices.Names.Contains(name))return;
            if(name!="Bing"&&name!=activeApi){apiStates[activeApi]=Snapshot();var preset=ApiServices.Get(name);Settings target;if(!apiStates.TryGetValue(name,out target)){target=new Settings();target.Values["base_url"]=preset.BaseUrl;target.Values["model"]=preset.Models[0];target.Key="";}syncingApi=true;try{foreach(string field in ApiServices.ApiFields)settings.Values[field]=target.Values[field];settings.Key=target.Key;activeApi=name;settings.Values["api_provider"]=name;}finally{syncingApi=false;}}
            settings.Values["provider"]=name;cache.Clear();Invalidate();SyncApiControls();UpdateProvider();
        }
        void SetApiUrl(string value){if(syncingApi)return;var preset=ApiServices.ForUrl(value);if(preset!=null&&preset.Name!=settings.Text("provider")){provider.SelectedItem=preset.Name;}settings.Values["base_url"]=value;Invalidate();UpdateEndpointNote();}
