        void UpdateRgbFields(){if(rgbFields==null)return;var arr=settings.Values["custom_rgb"] as object[];for(int i=0;i<3;i++)rgbFields[i].Text=arr!=null&&arr.Length==3?Convert.ToString(arr[i]):"250";}
        void ApplyTheme(){string theme=settings.Text("theme");foreach(var button in themeButtons)button.IsChecked=Convert.ToString(button.Tag)==theme;Color bg=Color.FromRgb(250,250,250);if(theme=="深色")bg=Color.FromRgb(21,21,21);else if(theme=="豆沙色")bg=Color.FromRgb(221,233,220);else if(theme=="自定义"){try{var a=(object[])settings.Values["custom_rgb"];bg=Color.FromRgb(Convert.ToByte(a[0]),Convert.ToByte(a[1]),Convert.ToByte(a[2]));}catch{}}
