        }
        void ApplyFont(){if(source==null)return;string family=settings.Text("font_family");try{if(family.Contains("://")||family.Contains("#")||!Native.ValidFont(family))family="Microsoft YaHei UI";}catch{family="Microsoft YaHei UI";}var font=new FontFamily(family+", Microsoft YaHei UI, Segoe UI");foreach(var editor in new[]{source,output}.Concat(editorHints))editor.SetReadingFormat(font,settings.Number("font_size",11)*96.0/72.0,settings.Text("font_style").Contains("粗")?FontWeights.Bold:FontWeights.Normal,settings.Text("font_style").Contains("斜")?FontStyles.Italic:FontStyles.Normal,settings.Text("line_spacing_mode"),settings.Number("line_spacing",20),settings.Number("line_spacing_multiple",1));}

        bool ApplyScreenshotText(string recognized){string prepared=TextTools.Prepare(recognized,settings.Flag("join_lines"),settings.Flag("repair_hyphens"));if(string.IsNullOrWhiteSpace(prepared)){SetStatus(L("未识别到文字；请检查识别模型或 Bing OCR 语言，并框选清晰文字重试","No text recognized. Select a clear text region and retry."));return false;}history.Reset();SetSource(prepared);output.Clear();if(LooksSensitive(prepared)){SetStatus(L("截图文字疑似含密钥，已跳过自动翻译","Possible secret in screenshot text; automatic translation skipped."));return false;}return true;}
        async void StartScreenshot(){
            if(captureSelfTest){SetStatus(L("取词自检模式不执行截图识别","Screenshot recognition is disabled during offline self-test"));return;}
            if(closing||screenshotBusy)return;FlushEdit();Invalidate();screenshotBusy=true;screenshotCancel=new CancellationTokenSource();var token=screenshotCancel.Token;UpdateActionButtons();UpdateCaptureState();bool readyToTranslate=false;
            try {
                ShowPage(0);SetStatus(L("拖动框选屏幕文字，Esc 或右键取消","Select screen text; Esc or right click cancels"));Hide();await Task.Delay(120,token);
                screenshotSelection=new ScreenshotSelection();var area=await screenshotSelection.Start(token);screenshotSelection.Dispose();screenshotSelection=null;
                if(area==null){if(!closing)SetStatus(L("截图已取消","Screenshot cancelled."));return;}
                await Task.Delay(100,token);var image=ScreenshotSelection.Capture(area.Value);if(!closing){Show();Activate();SetStatus(L("正在识别截图文字…","Recognizing screenshot text…"));}
                var screenshotSettings=Snapshot();SetStatus(screenshotSettings.Text("provider")=="Bing"?L("正在使用 Windows 识别…","Recognizing with Windows OCR…"):L("正在使用 AI 识别截图原文…","Recognizing screenshot with AI…"));var recognized=await ScreenshotOcr.RecognizeWithServiceAsync(image,screenshotSettings,token);token.ThrowIfCancellationRequested();if(closing)return;
                readyToTranslate=ApplyScreenshotText(recognized);
            }catch(OperationCanceledException){if(!closing)SetStatus(L("截图识别已取消","Screenshot recognition cancelled."));}
            catch(Exception error){if(!closing)SetStatus(L("截图识别失败：","Screenshot recognition failed: ")+error.Message);}
            finally {screenshotSelection?.Dispose();screenshotSelection=null;screenshotBusy=false;screenshotCancel?.Dispose();screenshotCancel=null;if(!closing){if(!IsVisible){Show();Activate();}UpdateCaptureState();UpdateActionButtons();source.Focus();}}
            if(readyToTranslate&&!closing)Translate();
        }
        void UpdateCaptureState(){bool enabled=!closing&&!screenshotBusy&&pause.IsChecked!=true;try{selectionCapture.SetEnabled(enabled);if(enabled)captureTimer.Start();else captureTimer.Stop();}catch(Exception error){captureTimer.Stop();pause.IsChecked=true;UpdateCaptureLabel();SetStatus(L("划词模块无法启用：","Capture unavailable: ")+error.Message);}}
        void UpdateCaptureLabel(){if(pause!=null)pause.Content=pause.IsChecked==true?L("划词：已暂停","Capture: paused"):L("划词：已开启","Capture: on");}
        void UpdateActionButtons(){if(source!=null)source.IsReadOnly=screenshotBusy;if(translateButton!=null){translateButton.IsEnabled=source!=null&&!string.IsNullOrWhiteSpace(source.Text)&&!translating&&!screenshotBusy;translateButton.Content=retryNeeded?L("重试","Retry"):L("翻译","Translate");}if(copyButton!=null)copyButton.IsEnabled=output!=null&&!string.IsNullOrWhiteSpace(output.Text);if(cancelButton!=null)cancelButton.Visibility=translating||screenshotBusy?Visibility.Visible:Visibility.Collapsed;if(screenshotButton!=null)screenshotButton.IsEnabled=!screenshotBusy;}
