        string SettingsSignature(){return Json.Stringify(settings.Values)+"\n"+settings.Key;}
        void QueueSettingsFeedback(){if(closing||currentPage==0||feedbackQueued)return;feedbackQueued=true;Dispatcher.BeginInvoke(new Action(()=>{feedbackQueued=false;if(closing)return;UpdateProvider();string message=SettingsSignature()==savedSignature?L("设置已保存","Settings saved."):L("有未保存的更改 · 点击保存设置后，下次启动仍会保留","Unsaved changes · Save settings to keep them after restart.");if(settingsFeedback!=null)settingsFeedback.Text=message;foreach(var notice in settingsNotices)notice.Text=message;}),DispatcherPriority.Background);}
        FrameworkElement SettingsNavigation(){var group=new StackPanel();var tabs=new WrapPanel{Margin=new Thickness(0,0,0,16)};string[] zh={"阅读与划词","外观主题","界面语言","翻译服务"},en={"Reading & capture","Appearance","Language","Translation service"};for(int i=0;i<4;i++){int page=i+1;string label=zh[i],english=en[i];var button=new ToggleButton{Content=L(label,english),Margin=new Thickness(0,0,8,6),MinHeight=30};Resource(button,Control.BackgroundProperty,"Field");translations.Add(()=>button.Content=L(label,english));button.Click+=(s,e)=>ShowPage(page);settingsTabs.Add(Tuple.Create(button,page));tabs.Children.Add(button);}group.Children.Add(tabs);var notice=Text("设置已保存","Settings saved.");notice.Margin=new Thickness(0,0,0,16);Resource(notice,TextBlock.ForegroundProperty,"Muted");settingsNotices.Add(notice);group.Children.Add(notice);return group;}
