        void UpdateCounts(){UpdateActionButtons();if(counts!=null){bool language=English;if(!ReferenceEquals(countSource,source.Text)||countEnglish!=language){countSource=source.Text;sourceCount=TextTools.Counts(countSource,language);}if(!ReferenceEquals(countOutput,output.Text)||countEnglish!=language){countOutput=output.Text;outputCount=TextTools.Counts(countOutput,language);}countEnglish=language;counts.Text=L("原文 ","Source ")+sourceCount+"  |  "+L("译文 ","Translation ")+outputCount;}}
