        string CompletedStatus(string text,Settings selected){return L("翻译完成","Translation complete.");}
        void PresentTranslation(string text){
            text=(text??"").Replace("\r\n","\n").Replace('\r','\n');
            if(closing)return;
            if(!SystemParameters.ClientAreaAnimation||text.Length==0){revealTimer.Stop();revealTarget=null;output.Text=text;return;}
            if(text==revealTarget||text==output.Text)return;
            // Long OCR passages must not rebuild RichTextBox layout on every animation frame.
            if(text.Length>2000){revealTimer.Stop();revealTarget=null;bool first=output.Text.Length==0;output.Text=text;if(first)output.BeginAnimation(UIElement.OpacityProperty,new DoubleAnimation(.35,1,TimeSpan.FromMilliseconds(180)){FillBehavior=FillBehavior.Stop});return;}
            if(!text.StartsWith(output.Text,StringComparison.Ordinal)){revealTimer.Stop();output.Clear();}
            revealTarget=text;revealElements=System.Globalization.StringInfo.ParseCombiningCharacters(text);
            revealStart=output.Text.Length;revealTick=Environment.TickCount;revealTimer.Start();
        }
        void AdvanceTranslation(){
            if(closing||revealTarget==null){revealTimer.Stop();return;}
            double t=Math.Min(1,unchecked(Environment.TickCount-revealTick)/220.0);
            int end=revealStart+(int)Math.Ceiling((revealTarget.Length-revealStart)*(1-Math.Pow(1-t,2)));
            if(end<revealTarget.Length){int index=Array.BinarySearch(revealElements,end);if(index<0)index=~index;end=index<revealElements.Length?revealElements[index]:revealTarget.Length;}
            if(end>output.Text.Length)output.Text=revealTarget.Substring(0,end);
            if(t>=1||end>=revealTarget.Length){revealTimer.Stop();revealTarget=null;UpdateCounts();}
        }
        async void Translate(){if(captureSelfTest){SetStatus(L("自检模式不联网；请先关闭取词自检","Offline self-test mode; disable it before translating"));return;}FlushEdit();string text=TextTools.Prepare(source.Text,settings.Flag("join_lines"),settings.Flag("repair_hyphens"));if(text.Length==0){SetStatus(L("请先选择文字或输入原文","Select text or enter a source first."));return;}var snapshot=Snapshot();string cacheKey;try{cacheKey=Translation.CacheKey(text,snapshot);}catch(Exception error){ShowTranslationError(error.Message);return;}if(translating&&activeRequestKey==cacheKey)return;Invalidate();int version=requestVersion;if(cache.TryGetValue(cacheKey,out string found)){PresentTranslation(found);SetStatus(CompletedStatus(text,snapshot));RecordTranslation(text,found,snapshot.Text("provider"));return;}
            requestCancel?.Dispose();requestCancel=new CancellationTokenSource();var token=requestCancel.Token;activeRequestKey=cacheKey;translating=true;UpdateActionButtons();SetStatus(snapshot.Text("provider")!="Bing"&&snapshot.Flag("reasoning_enabled")&&!snapshot.Flag("economy_mode")?L("正在思考…","Thinking…"):L("正在翻译…","Translating…"));output.Clear();
            try{LocalDiagnostics.Record(CaptureStep.TranslationStarted);string result=await Translation.RunAsync(text,snapshot,token,progress=>{if(version==requestVersion&&!closing){SetStatus(L("正在接收译文…","Receiving translation…"));pendingProgress=progress;if(!renderTimer.IsEnabled)renderTimer.Start();}});if(version!=requestVersion||closing)return;pendingProgress=null;renderTimer.Stop();PresentTranslation(result);cache.Add(cacheKey,result);LocalDiagnostics.Record(CaptureStep.TranslationDone);SetStatus(CompletedStatus(text,snapshot));RecordTranslation(text,result,snapshot.Text("provider"));}
            catch(OperationCanceledException){if(version==requestVersion&&!closing)ShowTranslationError(L("请求超时，请重试或降低思考等级。","Request timed out. Retry or lower thinking effort."));}
            catch(Exception error){if(version==requestVersion&&!closing)ShowTranslationError(token.IsCancellationRequested?L("请求超时，请重试。","Request timed out. Please retry."):error.Message);}
            finally{if(version==requestVersion){translating=false;UpdateActionButtons();pendingProgress=null;renderTimer.Stop();}}
        }
        async void TestConnection(){if(captureSelfTest){SetStatus(L("请先关闭取词自检，再测试连接","Disable offline self-test before testing the connection"));return;}if(testButton==null)return;testCancel?.Cancel();testCancel?.Dispose();testCancel=new CancellationTokenSource();int version=++testVersion;testButton.IsEnabled=false;testStatus.Text=L("正在测试…","Testing…");try{var snapshot=Snapshot();string result=await Translation.RunAsync("Hello",snapshot,testCancel.Token);if(version==testVersion&&!closing){LocalDiagnostics.Record(CaptureStep.ServiceOk);testStatus.Text=L("连接成功 · ","Connected · ")+result;}}catch(Exception error){if(version==testVersion&&!closing){LocalDiagnostics.Record(CaptureStep.ServiceError);testStatus.Text=error.Message;}}finally{if(version==testVersion&&!closing)testButton.IsEnabled=true;}}
    }
